  const today = () => new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Shanghai', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
  const status = (event, day = today()) => {
    const start = event.date.length === 7 ? event.date + '-01' : event.date;
    let end = event.endDate || event.date;
    if (end.length === 7) end = new Date(Date.UTC(Number(end.slice(0,4)), Number(end.slice(5)), 0)).toISOString().slice(0,10);
    return end < day ? 'past' : start > day ? 'upcoming' : 'ongoing';
  };
  const daysUntil = (date, day = today()) => Math.max(0, Math.round((Date.parse(date + 'T00:00:00Z') - Date.parse(day + 'T00:00:00Z')) / 86400000));
  const escapeHTML = (value = '') => String(value).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const cleanScheduleText = text => text.replace(/（[^（）]*）|\([^()]*\)/g, '').trim();
  const archive = (globalThis.ScheduleArchive || []).map(record => ({
    ...record,
    title: cleanScheduleText(record.title),
    description: cleanScheduleText(record.description),
    activities: record.activities.map(activity => ({...activity, text: cleanScheduleText(activity.text)}))
  }));
  const timeline = archive.flatMap(record => record.activities.map((activity, index) => ({
    ...record, ...activity,
    id: record.id + '-activity-' + (index + 1),
    activityIndex: index,
    title: activity.text,
    description: activity.text,
    categories: [activity.category],
    activities: [activity]
  }))).filter(activity => !/开售|预售|发售/.test(activity.title));
  const all = [...events, ...magazines, ...works, ...lives, ...timeline];
  const categories = { fanmeeting: '见面活动', broadcast: '剧集播出', magazine: '杂志画报', shoot: '拍摄工作', live: '直播', brand: '品牌活动', interview: '访谈', material: '物料发布', social: '社交动态', practice: '课程与排练', travel: '出行', activity: '其他活动' };
  const categoryOf = item => item.category || item.type;
  const bounds = item => ({ start: item.date.length === 7 ? item.date + '-01' : item.date, end: (item.endDate || item.date).length === 7 ? (item.endDate || item.date) + '-31' : (item.endDate || item.date) });
  function filterSchedule({ artist = 'all', state = 'all', month = 'all', category = 'all', query = '' } = {}) {
    return search(query, timeline).filter(item => {
      const range = bounds(item);
      return (artist === 'all' || (item.activities ? item.activities.some(a => a.artist === artist) : item.artist === artist)) && (state === 'all' || status(item) === state) && (category === 'all' || (item.categories || [categoryOf(item)]).includes(category)) && (month === 'all' || (range.start <= month + '-31' && range.end >= month + '-01'));
    }).sort((a, b) => b.date.localeCompare(a.date) || a.activityIndex - b.activityIndex);
  }
  function search(query, items = all) {
    const words = query.trim().toLowerCase().split(/\s+/).filter(Boolean);
    return items.filter(item => words.every(word => [item.title, item.chinese, item.subtitle, item.city, item.english, item.date, item.description, item.transcript, categories[categoryOf(item)], item.interview?.qa.map(q => q.question + ' ' + q.answers.map(a => a.text).join(' ')).join(' '), item.interview?.sections.map(s => s.title + ' ' + s.paragraphs.join(' ')).join(' '), item.artist === 'both' ? '双人 金允植 朴时宇 KYS PSW' : artists.filter(a => a.id === item.artist).map(a => `${a.name} ${a.latin} ${a.initials}`).join(' ')].filter(Boolean).join(' ').toLowerCase().includes(word)));
  }
  function calendar(event) {
    const nextDay = new Date((event.endDate || event.date) + 'T00:00:00Z');
    nextDay.setUTCDate(nextDay.getUTCDate() + 1);
    const clean = text => String(text || '').replace(/\\/g, '\\\\').replace(/\r?\n/g, '\\n').replace(/,/g, '\\,').replace(/;/g, '\\;');
    return ['BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//Two Paths//Fan Archive//ZH', 'CALSCALE:GREGORIAN', 'BEGIN:VEVENT', `UID:${event.id}@two-paths.local`, `DTSTAMP:${new Date().toISOString().replace(/[-:]/g, '').replace(/\.\d{3}/, '')}`, `DTSTART;VALUE=DATE:${event.date.replace(/-/g, '')}`, `DTEND;VALUE=DATE:${nextDay.toISOString().slice(0, 10).replace(/-/g, '')}`, `SUMMARY:${clean(event.title)} · 金允植 & 朴时宇`, `LOCATION:${clean(event.venue || event.city || '')}`, `DESCRIPTION:${clean((event.time ? '开场时间：' + event.time + '。' : '') + '全天活动提醒；具体安排以主办方公告为准。')}`, 'TRANSP:TRANSPARENT', 'END:VEVENT', 'END:VCALENDAR', ''].join('\r\n');
  }
  globalThis.SiteData = { about, artists, events, magazines, works, lives, all, timeline, archive, categories, updated: '2026-10-30' };
  globalThis.SiteUtils = { today, status, daysUntil, escapeHTML, search, calendar, filterSchedule, categoryOf };
